const rev = $('Fetch Revenue KPIs').all().map(i=>i.json).slice(-30);
const cust = $('Fetch Customer KPIs').all().map(i=>i.json).slice(-30);
const prod = $('Fetch Product KPIs').all().map(i=>i.json).slice(-7);

const todayRev = parseFloat(rev[rev.length-1]?.['Revenue']||0);
const yestRev = parseFloat(rev[rev.length-2]?.['Revenue']||0);
const rev7 = rev.slice(-7).reduce((s,r)=>s+parseFloat(r['Revenue']||0),0);
const rev30 = rev.reduce((s,r)=>s+parseFloat(r['Revenue']||0),0);

const newCustToday = parseInt(cust[cust.length-1]?.['New Customers']||0);
const totalActive = parseInt(cust[cust.length-1]?.['Active Customers']||0);
const churnedToday = parseInt(cust[cust.length-1]?.['Churned']||0);

const revDod = yestRev > 0 ? (((todayRev-yestRev)/yestRev)*100).toFixed(1) : 0;

const topProduct = prod.sort((a,b)=>parseInt(b['Units Sold']||0)-parseInt(a['Units Sold']||0))[0];

return [{ json: {
  today: { revenue: todayRev, dod_change: parseFloat(revDod), new_customers: newCustToday, churned: churnedToday },
  week: { revenue: rev7 },
  month: { revenue: rev30, active_customers: totalActive },
  top_product: topProduct?.['Product'] || 'N/A',
  top_product_units: parseInt(topProduct?.['Units Sold']||0),
  date: new Date().toISOString().split('T')[0]
} }];

